import workflow as w
c=w.connect()
rows=[
('raw::308',959,'Q1','I_force_motion','Continuity, empirical outlet-flow calibration, log fitting, measurement uncertainty and two-tank clock design','All A-C tasks concern measuring tank dimensions and fall times, inferring outlet speed from volume conservation, fitting the explicitly given power law and speed ratio, and experimentally finding supply height/refill interval. No unsupplied viscous-flow constitutive law or fluid eigenmode calculation is required.',0,False),
('raw::309',957,'Q2','VI_electric_field','Resistor networks, voltage-divider calibration, digitization uncertainty and finite input-resistance loading','The ADC linear voltage-to-integer map and apparatus operation are supplied. A-C use ordinary circuit laws, uncertainty derivatives, statistics and circuit design. D requires identifying meter loading and eliminating its unknown input resistance by swapping the divider resistors; this is ordinary measurement physics, not semiconductor ADC theory.',1,True)]
out=[]
for uid,fid,label,dom,phy,reason,sol,focus in rows:
 u=c.execute('select * from units where screening_unit_id=?',(uid,)).fetchone();assert u and u['decision'] is None and u['source_file_id']==fid
 out.append(dict(screening_unit_id=uid,decision='KEEP',confidence='high',primary_spho_domains=dom,required_physics=phy,decision_reason=reason,external_physics_if_any='',format='experimental',page_start=1,page_end=6,visual_inspection_used=1,solution_used=sol,boundary_status='content_boundary_verified',needs_second_review=focus,evidence=f'Complete official APhO 2026 Experimental {label}, file {fid}: all six extracted pages read and all six rendered pages actually inspected, including apparatus photographs, wiring/leveling instructions, every internal task and supplied relation. One whole experimental parent. ADC official solution 956 pp8-13 read, with pp10-12 rendered to resolve input loading.'))
p=w.ROOT/'reviews/shutdown_apho_2026_experiments_2.json';w.writejson(p,out);w.decisions(p)
for uid,fid,label,*rest in rows:
 c.execute("update paper_boundary_audit set status='full_paper_boundaries_verified',observed_units=1,evidence=?,checked_at=? where file_id=?",(f'All six physical pages and apparatus images checked. Official Experimental {label}, one top-level task containing its complete internal parts. Acquisition number retained separately; no omitted independent problem.',w.now(),fid))
 c.execute('update units set source_quality_notes=? where screening_unit_id=?',(f'Official experimental label {label} differs from the acquisition sequential numbering; provenance and acquisition ID retained. Requires the described physical apparatus for future performance. Screening inspected the statement, not performed measurements; no experimental results invented.',uid))
c.commit()
reviews=[dict(screening_unit_id='raw::309',detail='Focused measurement-model review and experimental-format seeded QC Random(2026100428) selects raw::309. Full six-page A-D statement and all apparatus/wiring images reread; official solution 956 pp10-12 rendered because extracted formula glyphs were broken. Finite input resistance Ri lies parallel to the grounded divider resistor. Swapped measurements give Va/Vc=R*Ri/(rR+rRi+RRi), Vb/Vc=r*Ri/(rR+rRi+RRi), hence r=R*(Nb-NL)/(Na-NL). The unknown loading cancels using ordinary resistor circuit laws and the explicitly supplied linear ADC map. No microscopic converter model required. A-C calibration, quantization/error range and precision redesign also ordinary measurement/data analysis. Whole experimental KEEP confirmed. Official sample data are not measurements made in this screening.')]
p=w.ROOT/'reviews/shutdown_apho_2026_experiments_focused_seeded.json';w.writejson(p,reviews);w.review(p)
print('Saved two whole experimental decisions, two physical-paper audits, and focused/format QC.')
